function mapLinkFor(p){const c=C.coords(p);return isSynced(p)?(c?`https://www.openstreetmap.org/?mlat=${c[0]}&mlon=${c[1]}#map=16/${c[0]}/${c[1]}`:''):'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(c?c.join(','):p.address||p.name_kr)}
function detailHero(p){const n=mediaFor(p).length,saved=db.saved.includes(p.place_id),id=E(p.place_id);return `<div class="detail-hero${n?'':' no-photo'}">${art(p,'detail-art')}<div class="hero-controls"><button type="button" class="glass-button round hero-back" data-app-back aria-label="뒤로">${I('arrow-left')}</button><span class="hero-spacer"></span><button type="button" class="glass-button round" data-share="${id}" aria-label="링크 공유">${I('share-network')}</button><button type="button" class="glass-button round${saved?' saved':''}" data-save="${id}" aria-label="${E(p.name_kr)} ${saved?'저장 해제':'저장'}" aria-pressed="${saved}">${I(saved?'heart-fill':'heart')}</button></div>${n>1?`<button type="button" class="photo-count" data-scroll-to="detailPhotos">${I('images')}사진 ${n}장</button>`:''}</div>`}
function quickActions(p,mapURL){const id=E(p.place_id),saved=db.saved.includes(p.place_id);return `<div class="quick-actions"><button type="button" class="quick${saved?' saved':''}" data-save="${id}">${I(saved?'heart-fill':'heart')}<span>${saved?'저장됨':'저장'}</span></button><button type="button" class="quick" data-add-route="${id}" aria-label="코스에 담기">${I('path')}<span>코스</span></button>${mapURL?`<a class="quick" href="${E(mapURL)}" target="_blank" rel="noopener noreferrer">${I('map-trifold')}<span>지도</span></a>`:`<span class="quick disabled">${I('map-trifold')}<span>지도 없음</span></span>`}<button type="button" class="quick" data-share="${id}">${I('share-network')}<span>공유</span></button></div>`}
function actionBar(p,mapURL){return `<div class="detail-actionbar"><button type="button" class="button tonal large" data-add-route="${E(p.place_id)}">${I('path')}코스에 담기</button>${mapURL?`<a class="button large" href="${E(mapURL)}" target="_blank" rel="noopener noreferrer">${I('navigation-arrow')}지도에서 보기</a>`:''}</div>`}
function visitsSection(p){const id=E(p.place_id),vis=db.visits.filter(v=>v.placeId===p.place_id);return `<section class="detail-section" id="detailVisits"><div class="section-head"><h2>나의 현장 기록</h2><button class="button tonal small" data-visit="${id}">${I('plus')}기록</button></div>${vis.length?vis.map(visitHTML).join(''):'<p class="section-empty">첫 관찰을 남겨보세요. 빛의 움직임, 건축 외피, 관람 위치와 느낀 점을 기록할 수 있어요.</p>'}${db.legacyVisits[p.place_id]?`<p class="section-note">이전 버전 방문 횟수: ${db.legacyVisits[p.place_id]}회 · 날짜와 메모 없음</p>`:''}</section>`}
function routeCards(){return db.routes.length?`<div class="route-grid">${db.routes.map(r=>{const ps=r.stops.map(place).filter(Boolean),names=ps.map(p=>p.name_kr),tiles=ps.slice(0,3);return `<a class="collection route-card" href="#route/${E(r.id)}"><span class="route-mosaic n${Math.max(1,tiles.length)}" aria-hidden="true">${tiles.length?tiles.map(p=>`<span class="brand-art tone-${[0,2,3][tone(p.place_id)%3]}">${I(catIcon(p))}</span>`).join(''):`<span class="brand-art">${I('path')}</span>`}</span><span class="route-body"><h3>${E(r.name)}</h3><span class="route-meta">${r.stops.length}곳 · ${E(r.date||'날짜 미정')}</span>${names.length?`<span class="route-stops">${E(names.slice(0,3).join(' › '))}${names.length>3?' …':''}</span>`:'<span class="route-stops">아직 담은 장소가 없어요</span>'}</span>${I('caret-right','route-caret')}</a>`}).join('')}</div>`:''}
function groupRow(href,icon,title,value='',cls=''){return `<a class="group-row${cls?' '+cls:''}" href="${href}"><span class="row-ic">${I(icon)}</span><span class="row-title">${title}</span>${value?`<span class="row-value">${value}</span>`:''}${I('caret-right','row-chev')}</a>`}
function magazinePage(){return `<header class="page-head"><h1 class="large-title">빛의 건축 읽기</h1><p class="page-sub">공간과 빛에 대한 해설과 연구를 모았어요.</p></header>${articles().length?magazineCards():empty('아직 등록된 글이 없어요','공개 승인된 해설과 연구 글이 이곳에 실려요. 그동안 에디터 코스로 빛의 공간을 둘러보세요.',`<a class="button" href="#routes">${I('path')}에디터 코스 보기</a>`)}`}
function onScroll(){const root=document.documentElement;if(!root?.dataset)return;const y=window.scrollY||0,edge=root.dataset.page==='place'?Math.max(48,($('.detail-hero')?.offsetHeight||0)-64):24;root.toggleAttribute('data-scrolled',y>edge);if(root.dataset.page==='place')spyTabs();if(Math.abs(y-lastY)>8||y<=0){root.dataset.scrollDir=y>lastY&&y>200?'down':'up';lastY=y}}
function home(){const ps=allPlaces().filter(p=>p.origin!=='wikidata'&&inScope(p)),today=C.today(),has=p=>mediaFor(p).length>0,lit=ps.filter(has),heroes=[...lit.filter(p=>!isSynced(p)),...lit.filter(isSynced)].slice(0,6),now=ps.filter(p=>X.available(p,today)||X.status(p,today)==='ongoing').map(p=>[p,(X.available(p,today)?2:0)+(has(p)?1:0)]).sort((a,b)=>b[1]-a[1]).map(x=>x[0]).slice(0,6),photos=lit.filter(p=>!isSynced(p)).slice(0,6),picks=ps.filter(p=>(p.MVP_priority==='A'||p.mvp_priority==='A')&&!photos.includes(p)&&!now.includes(p)).map(p=>[p,has(p)?1:0]).sort((a,b)=>b[1]-a[1]).map(x=>x[0]).slice(0,6),regions=regionCounts(ps),korea=rail(ps,'korea'),world=rail(ps,'world'),gs=window.AOL_GLOBAL?.status,themes=D.curations.filter(c=>D.curation_places.some(x=>x.curation_id===c.curation_id&&ps.some(p=>p.place_id===x.place_id))),updates=ps.filter(p=>p.updated_at&&p.publication_status==='approved').sort((a,b)=>b.updated_at.localeCompare(a.updated_at)).slice(0,4),cats=X.categories.map(([key,name,icon])=>[key,name,icon,X.search(ps,{category:key},today).length]).filter(c=>c[3]),more=(attr,label='전체 보기')=>`<button type="button" class="text-link" ${attr}>${label}${I('caret-right')}</button>`;return `<div class="home-panel" aria-hidden="true"></div><header class="home-intro"><h1 class="home-title">빛이 머무는 공간,<br>나의 다음 발견.</h1><p class="home-sub">건축과 미디어아트를 찾아보고, 나만의 답사와 기록으로 이어가세요.</p></header><div class="home-search-wrap"><form id="homeSearch" class="search-pill" role="search">${I('magnifying-glass')}<input name="q" type="search" aria-label="통합 검색" placeholder="장소, 도시, 작가 검색" autocomplete="off"><button class="search-go" aria-label="검색">${I('arrow-right')}</button></form></div>${scopeControl('home-scope')}${cats.length?`<div class="chips category-rail" role="group" aria-label="프로젝트 유형">${cats.map(([key,name,icon,n])=>`<button class="chip category-tile" data-discover-category="${key}">${I(icon)}<span>${name}</span><span class="chip-count">${fmt(n)}<span class="sr-only">곳</span></span></button>`).join('')}</div>`:''}<div class="home-feature">${heroes.length?heroCarousel(heroes):heroEmpty(ps.length)}</div>${now.length?sectionCards('지금 볼 수 있는 빛의 공간','수록된 일정 기준 · 방문 전 공식 안내를 확인하세요',now,more('data-explore-state="ongoing"')):''}${photos.length?sectionCards('사진으로 살펴보는 공간','출처와 라이선스를 확인한 사진 · 촬영 정보는 상세에서',photos):''}${themes.length?`<section class="home-section"><div class="section-head"><div><h2>에디터가 엮은 답사 코스</h2><small>하나의 시선으로 여러 공간을 잇는 원본 코스</small></div><div class="section-tools"><a href="#routes" class="text-link">전체 코스${I('caret-right')}</a>${railNav()}</div></div><div class="curation-rail rail-scroll">${themes.map(collection).join('')}</div></section>`:''}${korea.length?sectionCards('전국의 빛','Wikidata 공동 편집 데이터 · 6시간마다 갱신',korea,more('data-country-link="대한민국"')):''}${world.length?sectionCards('세계의 빛','세계의 미디어파사드·라이트아트·빛 축제',world,more('data-discover-category="Global"')):''}${!korea.length&&!world.length&&gs==='loading'&&scope!=='seoul'?`<section class="home-section" aria-busy="true"><div class="section-head"><div><h2>전국·세계의 빛</h2><small role="status">장소를 불러오는 중…</small></div></div><div class="grid rail">${'<div class="sk-card" aria-hidden="true"><span class="sk sk-photo"></span><span class="sk sk-line w40"></span><span class="sk sk-line w70"></span></div>'.repeat(4)}</div></section>`:''}${picks.length?sectionCards('처음이라면 여기부터','아카이브가 먼저 소개하는 서울의 빛',picks):''}${regions.cities.length?`<section class="home-section"><div class="section-head"><div><h2>어디의 빛을 만나볼까요?</h2><small>도시별로 모아 봤어요</small></div></div>${regions.countries.length>1?`<div class="chips" role="group" aria-label="국가별 장소">${regions.countries.slice(0,12).map(([c,n])=>`<button class="chip" data-country-link="${E(c)}">${E(c)} · ${fmt(n)}곳</button>`).join('')}</div>`:''}<div class="region-grid">${regions.cities.slice(0,regions.cities.length>=7?7:regions.cities.length>=3?3:regions.cities.length).map(r=>regionTile(r,ps,regions.countries.length>1)).join('')}<a class="region-tile region-more" href="#explore"><span class="region-more-icon">${I('globe-hemisphere-east')}</span><span class="region-name">모든 지역</span><small>국가·도시로 찾아보기</small></a></div></section>`:''}${updates.length?sectionCards('새로 확인한 프로젝트','공개 승인된 최종 업데이트 기준',updates):''}${articles().length?`<section class="home-section"><div class="section-head"><h2>빛의 건축 읽기</h2><a class="text-link" href="#magazine">전체 보기${I('caret-right')}</a></div>${magazineCards()}</section>`:''}<aside class="archive-note"><span class="archive-icon">${I('seal-check')}</span><div><b>출처와 함께 보는 아카이브</b><p>운영시간·일정·사진 권리의 확인 상태를 함께 보여드려요. 방문 전에는 공식 안내를 확인하세요.</p><a class="text-link" href="#settings">데이터 상태 보기${I('caret-right')}</a></div></aside>`}
function collection(c,i){const links=D.curation_places.filter(x=>x.curation_id===c.curation_id&&place(x.place_id)).sort((a,b)=>a.order-b.order),n=links.length,p=links.map(x=>place(x.place_id)).find(x=>mediaFor(x).length);return `<article class="collection curation-card tone-${i%4}${p?' has-photo':''}">${p?art(p,'curation-photo'):''}<a class="curation-link" href="#curation/${E(c.curation_id)}"><span class="collection-number">${String(i+1).padStart(2,'0')}</span><span class="curation-body"><h3>${E(c.title)}</h3><span class="curation-sub">${E(c.subtitle||c.description)}</span><span class="curation-meta">${n}곳 · 원본 코스</span></span></a></article>`}
function filterHTML(){return catChips(scoped())}
function resultsHTML(){const ps=X.search(scoped(),filters,C.today()),shown=ps.slice(0,showCount),where=[filters.country,filters.city].filter(Boolean).join(' · ')||scopeLabel(),all=allPlaces(),sorts=[['relevance','추천순'],['newest','최신 등록순'],['updated','최근 수정순']];return `<div class="result-bar"><p class="result-meta" role="status"><b>${E(where)}</b> · ${fmt(ps.length)}곳</p><div class="result-tools"><label class="sort-control"><span class="sr-only">정렬</span><select data-search-filter="sort">${sorts.map(([v,t])=>`<option value="${v}" ${(filters.sort||'relevance')===v?'selected':''} ${v==='newest'&&!all.some(p=>p.created_at)||v==='updated'&&!all.some(p=>p.updated_at)?'disabled':''}>${t}</option>`).join('')}</select>${I('caret-down','sort-caret')}</label><div class="view-switch" role="group" aria-label="목록 모양"><button type="button" data-list-view="cards" aria-pressed="${listView==='cards'}" aria-label="카드로 보기">${I('squares-four')}</button><button type="button" data-list-view="rows" aria-pressed="${listView==='rows'}" aria-label="한 줄 목록으로 보기">${I('rows')}</button></div>${modeSwitch('explore')}</div></div>${activeChips()}${ps.length?`<div class="grid results${listView==='rows'?' rows':''}">${shown.map(listView==='rows'?rowCard:card).join('')}</div>${ps.length>shown.length?`<div class="more-row"><p class="tnum">${fmt(ps.length)}곳 중 ${fmt(shown.length)}곳</p><button class="button subtle" data-more>${fmt(Math.min(PAGE,ps.length-shown.length))}곳 더 보기</button></div>`:''}`:emptyResults()}`}
function explore(){const ps=scoped();return `<header class="page-head"><h1 class="large-title">발견</h1></header><div class="explore-head"><div class="search-row"><div class="search-box">${I('magnifying-glass')}<input class="search-field" id="placeSearch" type="search" aria-label="장소 통합 검색" value="${E(filters.q)}" placeholder="장소, 도시, 작가 검색" autocomplete="off"></div>${filterSheet(ps)}</div>${catChips(ps)}</div><div id="placeResults">${resultsHTML()}</div><section class="global-search"><div class="global-head"><span class="global-icon">${I('globe-hemisphere-east')}</span><div><h2>찾는 곳이 없나요?</h2><p>Wikidata 공개 데이터에서 세계의 빛 장소를 검색해요. 결과는 검토 전 후보예요.</p></div></div><div class="filterbar"><div class="search-box">${I('magnifying-glass')}<input id="globalSearch" class="search-field" type="search" value="${E(globalQuery)}" placeholder="예: teamLab Borderless" aria-label="세계 장소 검색"></div><button class="button" id="globalSearchButton" ${globalBusy?'disabled':''}>${globalBusy?'검색 중…':'세계 검색'}</button></div><div id="globalResults">${globalHTML()}</div></section><a class="float-map" href="#map">${I('map-trifold')}지도로 보기</a>`}
function globalHTML(){if(globalBusy)return '<p class="loading-line" role="status">외부 공개 데이터를 검색하고 있어요…</p>';if(globalError)return `<div class="notice warning" role="alert">${E(globalError)} <button class="button subtle small" data-retry-global>다시 시도</button></div>`;return globalResults.map(x=>`<div class="list-row"><span class="row-icon">${I('globe-hemisphere-east')}</span><div class="row-main"><h3>${E(x.name_kr)}</h3><p>${E(x.short_description)}</p>${link(x.source_url,'Wikidata 출처')}</div><button class="button subtle small" data-global-save="${E(x.place_id)}">${db.candidates.some(c=>c.place_id===x.place_id)?I('check')+'저장됨':I('plus')+'저장'}</button></div>`).join('')||'<p class="global-note">검색 버튼을 누를 때만 검색어를 외부 서비스에 보내요.</p>'}
function routesPage(){return `<header class="page-head with-action"><div><h1 class="large-title">나의 답사 코스</h1><p class="page-sub">장소의 순서를 정하고, 관찰할 질문을 적고, 현장으로 가져가세요.</p></div><button class="button" data-new-route>${I('plus')}새 코스</button></header>${routeCards()||empty('다음 답사를 설계해 보세요','새 코스를 만들거나 아래 에디토리얼 코스를 복사해서 시작하세요.')}<section class="home-section"><div class="section-head"><div><h2>에디토리얼 코스</h2><small>원본 자료의 코스 · 방문 전 운영 여부를 확인하세요</small></div><div class="section-tools"><a class="text-link" href="#calendar">일정 보기${I('caret-right')}</a>${railNav()}</div></div><div class="curation-rail rail-scroll">${D.curations.map(collection).join('')}</div></section>`}
function curationPage(c){if(!c)return notFound();const links=D.curation_places.filter(x=>x.curation_id===c.curation_id&&place(x.place_id)).sort((a,b)=>a.order-b.order);return `<header class="curation-hero brand-art"><p class="eyebrow">에디토리얼 코스</p><h1>${E(c.title)}</h1><p class="curation-desc">${E(c.description)}</p><div class="hero-meta"><span>${I('map-pin')}${links.length}곳</span><span>${I('clock')}${E(String(c.estimated_time||'소요시간 미정').replace(/(\d+(?:\.\d+)?)\s*-\s*(\d+(?:\.\d+)?)\s*hours?/i,'$1–$2시간').replace(/(\d+(?:\.\d+)?)\s*hours?/i,'$1시간'))}</span></div><button class="button on-dark" data-copy-curation="${E(c.curation_id)}">${I('copy')}내 코스로 복사</button><span class="hero-mark" aria-hidden="true">${I('arch')}</span></header><p class="notice">${I('info')}<span>수록 소요시간은 실제 이동 시간을 계산한 값이 아니에요. 복사한 뒤 순서를 자유롭게 바꿀 수 있어요.</span></p><ol class="timeline">${links.map((x,i)=>{const p=place(x.place_id);return `<li class="list-row stop-row"><span class="stop-number">${i+1}</span><span class="stop-thumb brand-art tone-${[0,2,3][tone(p.place_id)%3]}" aria-hidden="true">${I(catIcon(p))}</span><div class="row-main"><a href="#place/${E(p.place_id)}"><h3>${E(p.name_kr)}</h3></a><p>${E(x.editor_comment||[category(p),p.district||regionText(p)].filter(Boolean).join(' · '))}</p></div><button class="button tonal small" data-add-route="${E(p.place_id)}" aria-label="${E(p.name_kr)} 코스에 담기">${I('plus')}코스</button></li>`}).join('')}</ol>`}
function routePage(r){if(!r)return notFound();const id=E(r.id),stops=r.stops.map(pid=>[pid,place(pid)]),km=(a,b)=>{const x=a&&C.coords(a),y=b&&C.coords(b);if(!x||!y)return null;const rad=v=>v*Math.PI/180,dl=rad(y[0]-x[0]),dn=rad(y[1]-x[1]),h=Math.sin(dl/2)**2+Math.cos(rad(x[0]))*Math.cos(rad(y[0]))*Math.sin(dn/2)**2;return 6371*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h))},legs=stops.slice(1).map(([,p],i)=>km(stops[i][1],p)),total=legs.every(v=>v!==null)&&legs.length?legs.reduce((a,b)=>a+b,0):null;return `<header class="page-head route-head"><p class="eyebrow">답사 코스</p><h1>${E(r.name)}</h1><p class="route-facts tnum"><span>${I('map-pin')}${r.stops.length}곳</span><span>${I('calendar-blank')}${E(r.date||'날짜 미정')}</span>${total!==null?`<span>${I('path')}직선 약 ${total.toFixed(1)}km</span>`:''}</p></header><div class="route-layout"><div class="route-main"><div class="route-toolbar"><button class="button" data-route-picker="${id}">${I('plus')}장소 추가</button><button class="button subtle" data-route-ics="${id}">${I('calendar-plus')}일정 파일</button><button class="button subtle" data-print>${I('printer')}인쇄 · PDF</button><details class="menu"><summary class="button subtle icon-only" aria-label="코스 더보기">${I('dots-three')}</summary><div class="menu-list"><button type="button" class="menu-item" data-route-copy="${id}">${I('copy')}코스 복제</button><button type="button" class="menu-item destructive" data-route-delete="${id}">${I('trash')}코스 삭제</button></div></details></div>${r.stops.length?`<ol class="timeline">${stops.map(([pid,p],i)=>{const name=E(p?.name_kr||pid),leg=legs[i];return `<li class="list-row stop-row"><span class="stop-number">${i+1}</span><span class="stop-thumb brand-art tone-${[0,2,3][tone(pid)%3]}" aria-hidden="true">${I(catIcon(p))}</span><div class="row-main"><a href="#place/${E(pid)}"><h3>${name}</h3></a><p>${E(p?(p.address||[category(p),p.district||regionText(p)].filter(Boolean).join(' · ')||'주소 미확인'):'주소 미확인')}</p>${p?badge(p):''}${leg!==null&&leg!==undefined?`<p class="leg-meta tnum">${I('arrow-down','icon-sm')}다음 장소까지 직선 ${leg<1?Math.round(leg*1000)+'m':leg.toFixed(1)+'km'}</p>`:''}</div><div class="stop-actions"><button class="icon-button small" data-move="${id}" data-index="${i}" data-direction="-1" ${i===0?'disabled':''} aria-label="${name} 위로">${I('arrow-up')}</button><button class="icon-button small" data-move="${id}" data-index="${i}" data-direction="1" ${i===r.stops.length-1?'disabled':''} aria-label="${name} 아래로">${I('arrow-down')}</button><button class="icon-button small" data-remove-stop="${id}" data-stop="${E(pid)}" aria-label="${name} 코스에서 제거">${I('x')}</button></div></li>`}).join('')}</ol>`:empty('아직 장소가 없어요','장소 추가 버튼으로 첫 목적지를 정하세요.',`<button class="button" data-route-picker="${id}">${I('plus')}장소 추가</button>`)}<p class="notice">${I('info')}<span>순서는 직접 편집해요. 거리는 좌표가 있는 장소 사이의 직선거리이고, 실제 이동 경로와 시간은 계산하지 않아요. 일정 파일은 시간 미정의 종일 일정이에요.</span></p></div><aside class="route-aside"><form id="routeForm" class="panel route-form" data-route-id="${id}"><h2>코스 정보</h2><label class="field">코스 이름<input name="name" value="${E(r.name)}" maxlength="120" required></label><label class="field">답사 날짜<input name="date" type="date" value="${E(r.date)}"></label><label class="field">답사 질문 · 메모<textarea name="note" maxlength="2000" placeholder="관찰할 요소, 촬영 위치, 건축과 빛의 관계…">${E(r.note)}</textarea></label><button class="button" type="submit">변경 저장</button></form></aside></div><div class="print-only"><p>${E(r.date)}</p><p class="record-note">${E(r.note)}</p></div>`}
function savedPage(){const ps=db.saved.map(place).filter(Boolean),tabs=`<div class="segmented saved-tabs" role="radiogroup" aria-label="저장 목록">${[['places','장소',ps.length],['routes','코스',db.routes.length]].map(([v,t,n])=>`<button type="button" role="radio" aria-checked="${savedTab===v}" tabindex="${savedTab===v?0:-1}" data-saved-tab="${v}">${t} <span class="seg-count">${n}</span></button>`).join('')}</div>`;let body;if(savedTab==='routes')body=(routeCards()||empty('아직 만든 코스가 없어요','저장한 장소를 묶어 첫 답사 코스를 만들어 보세요.'))+`<div class="actions center-actions"><button class="button" data-new-route>${I('plus')}새 코스</button><a class="button subtle" href="#routes">${I('path')}코스 모두 보기</a></div>`;else if(!ps.length)body=empty('마음에 드는 빛을 저장해 보세요','카드의 하트를 누르면 이곳에 모여요.','<a class="button" href="#explore">'+I('compass')+'발견하러 가기</a>');else{const list=[...ps].reverse(),key=p=>savedSort==='region'?([X.region(p).country,X.region(p).city].filter(Boolean).join(' · ')||'지역 미확인'):category(p),groups=new Map();if(savedSort!=='recent')for(const p of list){const k=key(p);if(!groups.has(k))groups.set(k,[]);groups.get(k).push(p)}body=`<div class="saved-toolbar"><div class="chips sort-chips" role="group" aria-label="정렬">${[['recent','최근 저장'],['region','지역'],['type','유형']].map(([v,t])=>`<button type="button" class="chip ${savedSort===v?'active':''}" data-saved-sort="${v}" aria-pressed="${savedSort===v}">${t}</button>`).join('')}</div><div class="actions"><button class="button" data-saved-route>${I('path')}저장 장소로 코스 만들기</button><button class="button subtle" data-export-saved>${I('download-simple')}CSV 내보내기</button><a href="#account" class="button subtle">${I('arrows-clockwise')}동기화 상태</a></div></div>${savedSort==='recent'?`<div class="grid compact">${list.map(card).join('')}</div>`:[...groups].map(([name,l])=>`<div class="group-head"><h2>${E(name)}</h2><span class="tnum">${l.length}곳</span></div><div class="grid compact">${l.map(card).join('')}</div>`).join('')}`}return `<header class="page-head"><h1 class="large-title">저장</h1><p class="page-sub">마음에 남은 공간을 다음 답사로 이어 보세요.</p></header>${tabs}${body}`}
function visitHTML(v){const p=place(v.placeId),stars=`<span class="stars" role="img" aria-label="평가 ${v.rating}점 / 5점">${[1,2,3,4,5].map(n=>I(n<=v.rating?'star-fill':'star')).join('')}</span>`;return `<article class="visit-card"><div class="visit-top"><span class="visit-thumb brand-art tone-${[0,2,3][tone(v.placeId)%3]}" aria-hidden="true">${I(catIcon(p))}</span><div class="visit-meta"><a href="#place/${E(v.placeId)}"><h3>${E(p?.name_kr||v.placeId)}</h3></a><p><time datetime="${E(v.date)}">${E(v.date)}</time>${v.rating?stars:'<span>평가 없음</span>'}</p></div><div class="visit-menu"><button class="icon-button small" data-edit-visit="${E(v.id)}" aria-label="기록 편집">${I('pencil-simple')}</button><button class="icon-button small" data-delete-visit="${E(v.id)}" aria-label="기록 삭제">${I('trash')}</button></div></div><p class="record-note">${E(v.note||'메모 없음')}</p><div class="visit-actions"><button class="button subtle small" data-visit-photos="${E(v.id)}">${I('camera')}개인 사진</button><button class="button subtle small" data-save="${E(v.placeId)}">${db.saved.includes(v.placeId)?I('heart-fill')+'다시 볼 장소에 저장됨':I('heart')+'다시 볼 장소 저장'}</button></div></article>`}
function journalPage(){const visits=[...db.visits].sort((a,b)=>b.date.localeCompare(a.date)),legacy=Object.values(db.legacyVisits).reduce((a,b)=>a+b,0),months=new Map();for(const v of visits){const k=v.date.slice(0,7);if(!months.has(k))months.set(k,[]);months.get(k).push(v)}return `<header class="page-head with-action"><div><h1 class="large-title">현장 기록</h1><p class="page-sub">빛을 본 순간의 시선과 질문을 남겨요.</p></div><button class="button head-action" data-new-visit>${I('plus')}방문 기록</button></header><div class="stat-strip">${[[visits.length,'방문 기록'],[new Set(visits.map(v=>v.placeId)).size,'기록한 장소'],[db.routes.length,'답사 코스'],...(legacy?[[legacy,'이전 방문']]:[])].map(([n,t])=>`<div class="stat"><b>${fmt(n)}</b><span>${t}</span></div>`).join('')}</div><div class="journal-tools"><button class="button subtle small" data-export-visits ${visits.length?'':'disabled'}>${I('download-simple')}기록 CSV</button><a class="button subtle small" href="#settings">${I('upload-simple')}백업 · 복원</a></div>${visits.length?[...months].map(([k,vs])=>`<section class="month-group"><h2 class="month-head">${k.slice(0,4)}년 ${Number(k.slice(5))}월</h2>${vs.map(visitHTML).join('')}</section>`).join(''):empty('첫 관찰을 남겨보세요','관람 날짜와 메모로 나만의 빛 아카이브를 시작하세요.')}<button class="fab" data-new-visit aria-label="방문 기록 추가">${I('plus')}<span aria-hidden="true">기록</span></button>`}
function calendarPage(){const today=C.today(),start=p=>C.validDate(p.program_start)?p.program_start:p.program_end,all=allPlaces().filter(p=>p.content_type!=='permanent'&&(C.validDate(p.program_start)||C.validDate(p.program_end))).sort((a,b)=>start(a).localeCompare(start(b))),live=all.filter(p=>X.status(p,today)!=='ended'),past=all.filter(p=>X.status(p,today)==='ended').reverse(),plans=db.routes.filter(r=>r.date).sort((a,b)=>a.date.localeCompare(b.date)),block=(d,cls='')=>C.validDate(d)?`<span class="date-block${cls}"><b>${Number(d.slice(8))}</b><small>${Number(d.slice(5,7))}월</small></span>`:'<span class="date-block unknown"><b>?</b><small>미정</small></span>',S={ongoing:['ok','진행 중'],upcoming:['info','개막 예정'],ended:['off','종료'],unknown:['off','일정 확인 필요']},row=p=>{const [tone,label]=S[X.status(p,today)]||S.unknown;return `<div class="calendar-row">${block(start(p))}<div class="calendar-text"><a href="#place/${E(p.place_id)}"><h3>${E(p.name_kr)}</h3></a><p>${E(p.current_program||'프로그램명 미확인')}</p><p class="tnum">${E(p.program_start||'시작 미확인')} – ${E(p.program_end||'종료 미확인')}</p><div class="pill-row"><span class="pill ${tone}">${label}</span>${badge(p)}</div>${link(official(p),'공식 안내')}</div></div>`},months=new Map();for(const p of live){const k=start(p).slice(0,7);if(!months.has(k))months.set(k,[]);months.get(k).push(p)}const years=new Set([...months.keys()].map(k=>k.slice(0,4))),ml=k=>(years.size>1?k.slice(2,4)+'년 ':'')+Number(k.slice(5))+'월';return `<header class="page-head"><h1 class="large-title">빛을 만나는 일정</h1><p class="page-sub">전시·프로그램 일정과 나의 답사 계획을 함께 봐요.</p></header><section class="home-section first"><div class="section-head"><h2>나의 답사</h2><a class="text-link" href="#routes">코스 관리${I('caret-right')}</a></div>${plans.map(r=>`<a class="calendar-row${r.date<today?' past':''}" href="#route/${E(r.id)}">${block(r.date,r.date<today?' muted':'')}<div class="calendar-text"><h3>${E(r.name)}</h3><p class="tnum">${r.stops.length}곳 · ${E(r.date)}${r.date<today?' · 지난 답사':''}</p></div>${I('caret-right','row-chev')}</a>`).join('')||`<div class="section-empty">코스에 답사 날짜를 정하면 이곳에 모여요. <a class="text-link" href="#routes">코스 보기${I('caret-right')}</a></div>`}</section><section class="home-section"><div class="section-head"><div><h2>전시·기간형 프로그램</h2><small>수록된 일정이에요 · 운영 여부와 휴관일은 공식 출처에서 확인하세요</small></div></div>${months.size>1?`<div class="chips month-strip" role="group" aria-label="월로 이동">${[...months].map(([k,l])=>`<button type="button" class="chip" data-scroll-to="month-${k}">${ml(k)}<span class="chip-count">${l.length}</span></button>`).join('')}</div>`:''}${[...months].map(([k,l])=>`<div class="month-group" id="month-${k}"><h3 class="month-head">${k.slice(0,4)}년 ${Number(k.slice(5))}월</h3>${l.map(row).join('')}</div>`).join('')||empty('지금 진행 중이거나 예정된 일정이 없어요','상설 장소에는 종료일을 임의로 붙이지 않아요.')}${past.length?`<details class="past-list"><summary>종료된 프로그램 ${past.length}개</summary>${past.map(row).join('')}</details>`:''}</section>`}
function settings(){const counts=D.places.reduce((a,p)=>{const k=C.freshness(p).key;a[k]=(a[k]||0)+1;return a},{}),theme=db.preferences?.theme||'system',user=window.AOLCloud?.state?.user;return `<header class="page-head"><h1 class="large-title">설정</h1><p class="page-sub">기기 기록은 오프라인에서도 보관돼요. 계정을 연결하면 여러 기기에서 이어볼 수 있어요.</p></header>${storageBlocked?`<p class="notice warning">${E(loaded.warning)}</p>`:''}<h2 class="group-caption">화면</h2><section class="group settings-display"><div class="group-row static"><span class="row-ic">${I('circle-half')}</span><span class="row-title" id="themeLabel">테마</span><div class="segmented" role="radiogroup" aria-labelledby="themeLabel">${[['system','시스템','circle-half'],['light','라이트','sun'],['dark','다크','moon']].map(([v,t,ic])=>`<button type="button" role="radio" aria-checked="${theme===v}" tabindex="${theme===v?0:-1}" data-theme-set="${v}">${I(ic)}${t}</button>`).join('')}</div></div></section><h2 class="group-caption">데이터 동기화</h2><section class="group panel sync-group"><div class="group-row static group-intro"><span class="row-ic">${I('cloud-check')}</span><span class="row-text"><span class="row-title">장소 사진·정보 동기화</span><span class="row-sub">Wikidata·Wikimedia Commons에서 6시간마다 갱신해요. 전국·세계의 빛 장소 목록도 함께 가져오고, 사진마다 촬영자·라이선스·원본 링크를 표시해요.</span></span></div><dl class="kv-list"><div class="kv"><dt>마지막 동기화</dt><dd id="liveSyncTime">${E(window.AOL_LIVE?.fetchedAt?syncTime(window.AOL_LIVE.fetchedAt):'아직 없음')}${window.AOL_LIVE?.status==='stale'?' · 최근 갱신 실패, 이전 결과 사용 중':''}</dd></div><div class="kv"><dt>연결된 장소 / 사진</dt><dd>${Object.keys(window.AOL_LIVE?.info||{}).length}곳 / ${(window.AOL_LIVE?.media||[]).length}장</dd></div>${globalSyncRows()}</dl><button type="button" class="group-row row-button" data-live-refresh><span class="row-ic">${I('arrows-clockwise')}</span><span class="row-title">지금 동기화</span></button></section><h2 class="group-caption">나의 데이터</h2><section class="group">${groupRow('#account','user-circle','계정 및 동기화',user?'로그인됨':'비회원')}<button type="button" class="group-row row-button" data-backup><span class="row-ic">${I('download-simple')}</span><span class="row-title">JSON 백업</span></button><button type="button" class="group-row row-button" data-restore><span class="row-ic">${I('upload-simple')}</span><span class="row-title">백업 복원</span></button><button type="button" class="group-row row-button destructive" data-reset><span class="row-ic">${I('trash')}</span><span class="row-title">기록 초기화</span></button></section><p class="group-note">백업에는 저장 장소, 코스, 방문 메모, 세계 검색 저장 후보가 들어가요. 복원하면 현재 데이터를 바꿔요.</p><input id="backupInput" class="hidden" type="file" accept="application/json,.json"><h2 class="group-caption">앱</h2><section class="group"><div class="group-row static"><span class="row-ic">${I(navigator.onLine?'globe':'wifi-slash')}</span><span class="row-text"><span class="row-title">${navigator.onLine?'온라인':'오프라인'}</span><span class="row-sub">외부 검색과 사진은 네트워크가 필요해요. 기본 장소와 개인 기록은 첫 접속 뒤 오프라인에서도 볼 수 있어요.</span></span></div><button type="button" class="group-row row-button" data-install><span class="row-ic">${I('device-mobile')}</span><span class="row-title">홈 화면에 설치</span></button></section><h2 class="group-caption">데이터 상태</h2><section class="group"><dl class="kv-list"><div class="kv"><dt>화면용 원본</dt><dd>${D.places.length}곳</dd></div><div class="kv"><dt>좌표 보유</dt><dd>${D.places.filter(C.coords).length}곳</dd></div><div class="kv"><dt>재확인 시점 경과</dt><dd>${counts.stale||0}곳</dd></div></dl><button type="button" class="group-row row-button" data-audit-csv><span class="row-ic">${I('download-simple')}</span><span class="row-title">검토 목록 CSV</span></button>${groupRow('#audit','list-checks','검토 목록 보기')}</section><p class="group-note">판정 기준: 서울 날짜 기준 (오늘 − 기존 확인일) ≥ refresh_days. 프로그램 종료일이 지났으면 종료를 먼저 표시해요. 권리·운영정보를 이번 버전에서 새로 검증한 것으로 표시하지 않아요.</p><h2 class="group-caption">개인정보와 외부 서비스</h2><section class="group text-group"><p>기록·코스·저장 목록은 이 브라우저의 localStorage에 보관합니다. 비회원 기록은 이 기기에만 보관합니다. 로그인하여 작성하거나 이관에 동의한 기록은 연결된 Supabase 서버로 전송됩니다. 세계 검색 시 검색어가 Wikidata에, 이미지 조회 시 장소명이 Wikimedia Commons에 전송됩니다. 장소 목록 동기화는 6시간마다 고정된 조회만 보내며 개인 기록을 포함하지 않습니다. 외부 지도·공식 사이트는 새 창에서 열립니다. 방문 기록과 코스 메모는 외부 검색에 포함하지 않습니다.</p><p>비공개 호스팅의 접속·인증 처리는 호스팅 제공자의 정책을 따릅니다. 백업 파일에 개인 메모가 포함될 수 있으므로 공유 전에 확인하세요.</p></section><h2 class="group-caption">법적 고지</h2><section class="group">${groupRow('./privacy.html','file-text','개인정보 처리방침')}${groupRow('./terms.html','scroll','이용 안내')}${groupRow('./support.html','lifebuoy','지원 및 문의')}${groupRow('./delete-account.html','user','계정 삭제 안내')}</section><p class="version-foot">빛의 건축 v0.15.0</p>`}
function auditPage(){return `<header class="page-head with-action"><div><h1 class="large-title">데이터 검토 목록</h1><p class="page-sub">원본 데이터를 바꾸지 않고, 다시 확인할 항목을 모아 봐요.</p></div><button class="button subtle" data-audit-csv>${I('download-simple')}CSV 내보내기</button></header><div class="table-scroll"><table class="audit-table"><thead><tr><th scope="col">장소</th><th scope="col">판정</th><th scope="col">기존 확인일</th><th scope="col">갱신 주기</th><th scope="col">출처</th></tr></thead><tbody>${[...D.places].sort((a,b)=>(a.verified_at||'').localeCompare(b.verified_at||'')).map(p=>`<tr><td><a href="#place/${E(p.place_id)}">${E(p.name_kr)}</a></td><td>${badge(p)}</td><td>${E(p.verified_at||'없음')}</td><td>${p.refresh_days||30}일</td><td>${link(official(p),'확인')}</td></tr>`).join('')}</tbody></table></div>`}
// After each render, the Wikidata sync rights-checks the photos of the synced places now on screen (lazily).
function wantShown(html,extra=[]){const ids=new Set(extra.filter(x=>/^WD-Q\d+$/.test(x||'')));for(const m of String(html||'').matchAll(/#place\/(WD-Q\d+)/g))ids.add(m[1]);if(ids.size)window.AOLGlobal?.wantImages?.([...ids])}
function showResults(){const el=$('#placeResults');if(!el)return;el.innerHTML=resultsHTML();wantShown(el.innerHTML)}
// Background data arrived (sync result, cleared photos): refresh the screen without taking away a field being typed
// in or reloading a map that is open.
function softRender(){const [page]=pagePath(),a=document.activeElement,typing=!!a&&/^(INPUT|TEXTAREA|SELECT)$/.test(a.tagName||'')&&!!$('#view')?.contains?.(a);if(page==='map'&&currentMap){updateMapResults();return}if(typing){if(page==='explore')showResults();else if(page==='map')updateMapList();return}render()}
function notFound(){return `<div class="empty empty-page"><span class="empty-mark">${I('arch')}</span><h1>페이지를 찾을 수 없어요</h1><p>삭제된 코스이거나 이 기기에 없는 개인 기록일 수 있어요.</p><div class="actions center-actions"><a class="button" href="#home">${I('house')}홈으로</a><a class="button subtle" href="#explore">${I('compass')}발견하기</a></div></div>`}
function render(){const wasMap=typeof currentMap!=='undefined'&&!!currentMap;if(typeof currentMap!=='undefined'&&currentMap){currentMap.remove();currentMap=null;mapMarkers=[];mapLayer=null;mapRenderer=null;mapShown=[];clearTimeout(mapTimer)}const theme=db.preferences?.theme||'system';document.documentElement?.setAttribute('data-theme',theme);document.querySelectorAll?.('meta[name="theme-color"]').forEach(m=>{const dark=theme==='dark'||theme==='system'&&/dark/.test(m.getAttribute('media')||'');m.setAttribute('content',dark?'#0D0F26':'#1C1F4A')});const [page,id]=pagePath();const active=['place','audit','magazine','article'].includes(page)?'explore':['route','routes','curation','calendar','account','settings','journal'].includes(page)?'my':page;const tab=navItems.find(n=>n[0]===page);document.documentElement?.setAttribute('data-page',page);document.documentElement?.setAttribute('data-level',tab?'top':'sub');const bar=$('#appBarTitle');if(bar)bar.textContent=tab?(page==='home'?'':tab[2]):page==='place'&&place(id)?place(id).name_kr:SUB_TITLES[page]||'빛의 건축';$('#navigation').innerHTML=navItems.map(([key,icon,title])=>`<a class="nav-link ${key===active?'active':''}" href="#${key}" ${key===active?'aria-current="page"':''}><span class="nav-icon">${I(key===active?icon+'-fill':icon)}</span><span class="nav-label">${title}</span>${key==='saved'&&db.saved.length?`<span class="nav-count">${db.saved.length}<span class="sr-only">곳</span></span>`:''}</a>`).join('');let html;switch(page){case 'my':html=myPage();break;case 'magazine':html=magazinePage();break;case 'article':html=articlePage(id);break;case 'home':html=home();break;case 'explore':html=explore();break;case 'map':html=mapPage();break;case 'place':html=!place(id)&&/^WD-Q\d+$/.test(id||'')&&['loading',undefined].includes(window.AOL_GLOBAL?.status)?'<div class="detail sk-detail" aria-busy="true"><span class="sk sk-hero" aria-hidden="true"></span><p class="loading-line" role="status">Wikidata 장소 정보를 불러오는 중…</p><span class="sk sk-line w60" aria-hidden="true"></span><span class="sk sk-line w40" aria-hidden="true"></span><span class="sk sk-block" aria-hidden="true"></span></div>':detail(place(id));break;case 'routes':html=routesPage();break;case 'route':html=routePage(route(id));break;case 'curation':html=curationPage(D.curations.find(c=>c.curation_id===id));break;case 'saved':html=savedPage();break;case 'journal':html=journalPage();break;case 'calendar':html=calendarPage();break;case 'account':html=window.AOLAccount?window.AOLAccount.page():heading('','계정 연결 준비 중','잠시 후 다시 열어주세요.');break;case 'settings':html=settings();break;case 'audit':html=auditPage();break;default:html=notFound()}const view=$('#view'),entering=page+'/'+(id||'')!==lastPath;lastPath=page+'/'+(id||'');view.classList.remove('view-enter');view.innerHTML=html;document.documentElement?.toggleAttribute?.('data-large',!!$('#view .large-title'));if(entering){void view.offsetWidth;view.classList.add('view-enter')}wantShown(html,page==='place'?[id]:[]);document.title=($('#view h1')?.textContent||'도시의 빛')+' · 빛의 건축';bindPage();railState();if(page==='place')spyTabs();if(page==='account')window.AOLAccount?.bind();if(page==='map'&&wasMap)loadMap()}
function modal(title,content){const el=$('#modal');el.innerHTML=`<div class="modal-head"><h2 id="modalTitle">${E(title)}</h2><button class="icon-button" type="button" data-close aria-label="닫기">${I('x')}</button></div>${content}`;if(!el.open)el.showModal();el.querySelector('[data-close]').onclick=()=>el.close();return el}
function confirmAction(title,text,fn){const el=modal(title,`<p>${E(text)}</p><div class="form-actions"><button class="button subtle" id="cancelConfirm">취소</button><button class="button danger" id="yesConfirm">확인</button></div>`);$('#cancelConfirm').onclick=()=>el.close();$('#yesConfirm').onclick=()=>{el.close();fn()}}
function newRoute(stops=[],name='나의 빛 답사'){const el=modal('새 답사 코스',`<form id="newRouteForm" class="form-grid"><label class="field">코스 이름<input name="name" value="${E(name)}" maxlength="120" required></label><label class="field">답사 날짜 (선택)<input type="date" name="date"></label><div class="form-actions"><button class="button" type="submit">코스 만들기</button></div></form>`);$('#newRouteForm').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target),r={id:C.id(),name:fd.get('name').trim(),date:fd.get('date'),note:'',stops:[...new Set(stops)].slice(0,50)};if(!r.name)return;if(change(d=>{d.routes.push(r);r.stops.forEach(id=>keep(d,id))})){el.close();go('route/'+r.id);toast('답사 코스를 만들었어요')}}}
function addToRoute(pid){if(!db.routes.length){newRoute([pid]);return}const el=modal('어느 코스에 담을까요?',`<div class="pick-list">${db.routes.map(r=>{const has=r.stops.includes(pid);return `<button type="button" class="pick-row" data-select-route="${E(r.id)}" ${has?'disabled':''}><span class="pick-ic">${I('path')}</span><span class="pick-text"><b>${E(r.name)}</b><small>${r.stops.length}곳${r.date?' · '+E(r.date):''}</small></span><span class="pick-state">${has?I('check')+'담겨 있어요':I('plus')+'<span class="sr-only">담기</span>'}</span></button>`}).join('')}</div><div class="form-actions"><button class="button tonal" id="newRouteForPlace">${I('plus')}새 코스 만들기</button></div>`);el.querySelectorAll('[data-select-route]').forEach(b=>b.onclick=()=>{const r=route(b.dataset.selectRoute);if(r.stops.length>=50){toast('한 코스에는 50곳까지 담을 수 있어요.');return}if(change(d=>{d.routes.find(x=>x.id===r.id).stops.push(pid);keep(d,pid)})){el.close();toast(`‘${r.name}’에 담았어요`,{label:'보기',fn:()=>go('route/'+r.id)})}});$('#newRouteForPlace').onclick=()=>newRoute([pid])}
function routePicker(rid){const el=modal('코스에 장소 추가',`<div class="search-box picker-search">${I('magnifying-glass')}<input class="search-field" id="pickerSearch" type="search" placeholder="장소 이름 검색" aria-label="추가할 장소 검색" autocomplete="off"></div><div id="pickerResults" class="pick-list"></div>`);function draw(){const r=route(rid),q=$('#pickerSearch').value,found=C.filterPlaces(allPlaces(),{q}).slice(0,30);$('#pickerResults').innerHTML=found.map(p=>{const has=r.stops.includes(p.place_id);return `<button type="button" class="pick-row" data-pick="${E(p.place_id)}" ${has?'disabled':''}><span class="pick-ic">${I(catIcon(p))}</span><span class="pick-text"><b>${E(p.name_kr)}</b><small>${E([category(p),regionText(p)||p.district].filter(Boolean).join(' · '))}</small></span><span class="pick-state">${has?I('check')+'추가됨':I('plus')+'<span class="sr-only">추가</span>'}</span></button>`}).join('')||'<p class="pick-empty">찾는 장소가 없어요. 다른 이름으로 검색해 보세요.</p>';el.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{if(r.stops.length>=50){toast('한 코스에는 50곳까지 담을 수 있어요.');return}if(change(d=>{d.routes.find(x=>x.id===rid).stops.push(b.dataset.pick);keep(d,b.dataset.pick)})){draw();render();toast('장소를 추가했어요')}})}$('#pickerSearch').oninput=draw;draw()}
function visitForm(pid='',visitId=''){const v=db.visits.find(x=>x.id===visitId)||{placeId:pid,date:C.today(),rating:0,note:''};const el=modal(visitId?'방문 기록 편집':'새 방문 기록',`<form id="visitForm" class="form-grid"><label class="field">장소<select name="placeId" required><option value="">장소 선택</option>${allPlaces().filter(p=>!isSynced(p)||p.place_id===v.placeId||db.saved.includes(p.place_id)||db.candidates.some(c=>c.place_id===p.place_id)).map(p=>`<option value="${E(p.place_id)}" ${v.placeId===p.place_id?'selected':''}>${E(p.name_kr)}</option>`).join('')}</select></label><label class="field">방문 날짜<input type="date" name="date" required max="${C.today()}" value="${E(v.date)}"></label><fieldset class="field rating-field"><legend>나의 평가</legend><div class="rating">${[1,2,3,4,5].map(n=>`<label class="star${n<=v.rating?' on':''}"><input type="radio" name="rating" value="${n}" ${v.rating===n?'checked':''}><span class="sr-only">${n}점</span>${I('star-fill')}</label>`).join('')}<label class="rating-none"><input type="radio" name="rating" value="0" ${v.rating?'':'checked'}><span>평가 없음</span></label></div></fieldset><label class="field">현장 메모<textarea name="note" maxlength="4000" placeholder="건축 외피와 빛의 관계, 시야, 밝기, 소리, 머무는 방식…">${E(v.note)}</textarea></label><div class="form-actions"><button class="button" type="submit">기록 저장</button></div></form>`);const stars=el.querySelector('.rating');if(stars)stars.onchange=e=>{const n=Number(e.target.value)||0;stars.querySelectorAll('.star').forEach((x,i)=>x.classList.toggle('on',i<n))};$('#visitForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),item={id:visitId||C.id(),placeId:f.get('placeId'),date:f.get('date'),rating:Number(f.get('rating')),note:f.get('note')};if(!place(item.placeId)||!C.validDate(item.date)||item.date>C.today()){toast('장소와 방문 날짜를 확인해 주세요.');return}if(change(d=>{if(visitId)d.visits=d.visits.map(x=>x.id===visitId?item:x);else d.visits.push(item);keep(d,item.placeId)})){el.close();render();toast('현장 기록을 저장했어요')}}}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function backup(){download('빛의건축_백업_'+C.today()+'.json',JSON.stringify({...db,exportedAt:new Date().toISOString()},null,2),'application/json')}
function exportSaved(){download('빛의건축_저장장소.csv',C.csv([['장소','지역','주소','출처'],...db.saved.map(place).filter(Boolean).map(p=>[p.name_kr,p.district||regionText(p),p.address,official(p)])]),'text/csv;charset=utf-8')}
function exportVisits(){download('빛의건축_방문기록.csv',C.csv([['날짜','장소','평가','메모'],...db.visits.map(v=>[v.date,place(v.placeId)?.name_kr,v.rating,v.note])]),'text/csv;charset=utf-8')}
function auditCSV(){download('빛의건축_갱신검토.csv',C.csv([['ID','장소','판정','기존 확인일','갱신주기(일)','좌표 상태','출처'],...D.places.map(p=>[p.place_id,p.name_kr,C.freshness(p).label,p.verified_at,p.refresh_days,C.coords(p)?'있음':'미확인',official(p)])]),'text/csv;charset=utf-8')}
async function importFile(file){if(!file)return;if(file.size>5*1024*1024){toast('백업 파일은 5MB 이하만 복원할 수 있어요.');return}try{const next=C.validate(JSON.parse(await file.text()),D.places.map(p=>p.place_id));confirmAction('백업으로 복원할까요?',`현재 기록을 저장 ${next.saved.length}곳, 코스 ${next.routes.length}개, 방문 ${next.visits.length}개로 교체합니다. 필요하면 먼저 현재 데이터를 백업하세요.`,()=>{if(!C.write(storage,next)){toast('저장하지 못했어요. 지금 기록은 그대로 있어요.');return}storageBlocked=false;db=next;render();toast('백업을 복원했어요')})}catch(e){toast('복원하지 못했어요: '+e.message)}}
async function fetchJSON(url){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);try{const r=await fetch(url,{signal:controller.signal,credentials:'omit'});if(!r.ok)throw Error('HTTP '+r.status);return await r.json()}finally{clearTimeout(timer)}}
async function searchGlobal(){const q=($('#globalSearch')?.value||globalQuery).trim();if(!q){toast('검색어를 입력해 주세요.');return}const seq=++searchSeq;globalQuery=q;globalBusy=true;globalError='';globalResults=[];render();try{const lang=/[가-힣]/.test(q)?'ko':'en';const s=await fetchJSON('https://www.wikidata.org/w/api.php?action=wbsearchentities&format=json&origin=*&language='+lang+'&uselang=ko&limit=12&search='+encodeURIComponent(q));const ids=(s.search||[]).map(x=>x.id).filter(x=>/^Q\d+$/.test(x));if(!ids.length){globalError='검색 결과가 없어요. 다른 이름이나 영문 이름으로 검색해 보세요.';return}const data=await fetchJSON('https://www.wikidata.org/w/api.php?action=wbgetentities&format=json&origin=*&props=labels|descriptions|claims&languages=ko|en&ids='+ids.join('|'));if(seq!==searchSeq)return;const claim=(e,k)=>e.claims?.[k]?.[0]?.mainsnak?.datavalue?.value;globalResults=ids.map(id=>{const e=data.entities?.[id];if(!e)return null;const coord=claim(e,'P625');return {place_id:'WD-'+id,name_kr:e.labels?.ko?.value||e.labels?.en?.value||id,name_en:e.labels?.en?.value||'',short_description:e.descriptions?.ko?.value||e.descriptions?.en?.value||'',primary_category:'Global',district:'세계 검색',origin:'wikidata',latitude:coord?.latitude??null,longitude:coord?.longitude??null,website:C.safeURL(claim(e,'P856')),source_url:'https://www.wikidata.org/wiki/'+id,image:claim(e,'P18')||'',verified_at:''}}).filter(Boolean)}catch(e){if(seq===searchSeq)globalError=navigator.onLine?'외부 검색에 실패했어요. 잠시 뒤 다시 시도해 주세요.':'오프라인에서는 세계 검색을 쓸 수 없어요.'}finally{if(seq===searchSeq){globalBusy=false;if(pagePath()[0]==='explore')render()}}}
async function loadPhoto(pid){const p=place(pid),box=$('#photoResult');if(!box)return;box.innerHTML='<p class="loading" role="status">이미지 메타데이터 확인 중…</p>';const strip=x=>{const doc=new DOMParser().parseFromString(String(x||''),'text/html');return doc.body.textContent||''};try{const params=p.image?'titles='+encodeURIComponent('File:'+p.image):'generator=search&gsrnamespace=6&gsrlimit=3&gsrsearch='+encodeURIComponent(p.name_en||p.name_kr);const data=await fetchJSON('https://commons.wikimedia.org/w/api.php?action=query&format=json&origin=*&prop=imageinfo&iiprop=url|extmetadata&iiurlwidth=1000&'+params);const records=Object.values(data.query?.pages||{}).map(pg=>{const i=pg.imageinfo?.[0],m=i?.extmetadata||{},license=strip(m.LicenseShortName?.value||m.UsageTerms?.value);return {title:pg.title,url:C.safeURL(i?.thumburl||i?.url),license,artist:strip(m.Artist?.value||m.Credit?.value),licenseURL:C.safeURL(m.LicenseUrl?.value),source:'https://commons.wikimedia.org/wiki/'+encodeURIComponent(pg.title||'')}}).filter(a=>a.url&&/^(CC BY(?:-SA)? [\d.]+|CC0(?: [\d.]+)?|Public domain)$/i.test(a.license));if(!box.isConnected)return;box.innerHTML=records.length?records.map(a=>`<figure style="margin:20px 0"><img class="photo" src="${E(a.url)}" alt="${E(a.title)} · 자동 검색 후보" loading="lazy" referrerpolicy="no-referrer"><figcaption class="photo-credit">${E(a.artist||'작성자 표기 확인 필요')} · ${E(a.license)}${link(a.source,'원본·장소 일치 여부 확인')}${link(a.licenseURL,'라이선스 조건')}</figcaption></figure>`).join('')+'<p class="notice">메타데이터 조건으로 선별한 자동 후보입니다. 사진 속 장소 일치와 개별 사용조건을 원본에서 확인하세요.</p>':'<p class="notice">자동 표시 조건에 맞는 이미지가 없어요. 기본 그래픽을 그대로 보여드려요.</p>'}catch{if(box.isConnected)box.innerHTML='<p class="notice warning">이미지를 가져오지 못했어요. 다시 시도하거나 공식 출처를 확인해 주세요.</p>'}}
function bindPage(){const handle=$('#mapHandle');if(handle){const ex=$('#mapExplorer'),det=()=>{const h=ex?.clientHeight||600,head=$('.map-head')?.getBoundingClientRect?.(),top=head&&ex?Math.max(0,Math.round(head.bottom-ex.getBoundingClientRect().top)):72;return [112,Math.round(h*.5),Math.max(160,h-top-4)]},set=(v,snap)=>{if(!ex)return;const d=det();if(snap)v=d.reduce((a,b)=>Math.abs(b-v)<Math.abs(a-v)?b:a);const hgt=Math.round(Math.max(96,Math.min(d[2],v)));ex.style.setProperty('--sheet-height',hgt+'px');ex.classList.toggle('sheet-dragging',!snap);sheetFull=hgt>=d[2]-8;ex.classList.toggle('sheet-full',sheetFull);if(snap)sheetH=hgt},now=()=>$('.map-list')?.getBoundingClientRect?.().height||det()[1];let start=null;handle.onpointerdown=e=>{start={y:e.clientY,h:now(),moved:false};handle.setPointerCapture?.(e.pointerId)};handle.onpointermove=e=>{if(!start)return;const dy=start.y-e.clientY;if(Math.abs(dy)>4)start.moved=true;if(start.moved)set(start.h+dy,false)};handle.onpointerup=e=>{if(!start)return;const s=start;start=null;if(s.moved){set(s.h+(s.y-e.clientY),true);return}const d=det(),i=d.reduce((bi,x,j)=>Math.abs(x-s.h)<Math.abs(d[bi]-s.h)?j:bi,0);set(d[(i+1)%d.length],true)};handle.onpointercancel=()=>{start=null;ex?.classList.remove('sheet-dragging')};handle.onkeydown=e=>{if(!['ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const d=det(),h=now(),i=d.reduce((bi,x,j)=>Math.abs(x-h)<Math.abs(d[bi]-h)?j:bi,0);set(d[Math.max(0,Math.min(d.length-1,i+(e.key==='ArrowUp'?1:-1)))],true)}}const hs=$('#homeSearch');if(hs)hs.onsubmit=e=>{e.preventDefault();filters={q:String(new FormData(hs).get('q')||''),category:'전체'};go('explore')};const input=$('#placeSearch');if(input)input.oninput=()=>{filters.q=input.value;showCount=PAGE;if(pagePath()[0]==='map'){clearTimeout(mapTimer);mapTimer=setTimeout(updateMapResults,MAP_TYPING_DELAY)}else showResults()};const district=$('#districtFilter');if(district)district.onchange=()=>{filters.district=district.value;showCount=PAGE;render()};const gs=$('#globalSearch');if(gs)gs.onkeydown=e=>{if(e.key==='Enter')searchGlobal()};const gb=$('#globalSearchButton');if(gb)gb.onclick=searchGlobal;const rf=$('#routeForm');if(rf)rf.onsubmit=e=>{e.preventDefault();const fd=new FormData(rf),name=fd.get('name').trim(),date=fd.get('date');if(!name||date&&!C.validDate(date))return;if(change(d=>Object.assign(d.routes.find(x=>x.id===rf.dataset.routeId),{name,date,note:fd.get('note')}))){render();toast('코스를 저장했어요')}};const bi=$('#backupInput');if(bi)bi.onchange=()=>importFile(bi.files[0]);const adv=$('.advanced-filters');if(adv)adv.ontoggle=()=>{advancedOpen=adv.open}}
