window.addEventListener('storage',e=>{if(e.key===(activeUser?'aol12_user_'+activeUser:C.KEY)&&e.newValue){try{db=C.validate(JSON.parse(e.newValue),D.places.map(p=>p.place_id));storageBlocked=false;render();toast('다른 탭에서 바꾼 내용을 반영했어요')}catch{toast('다른 탭의 데이터를 읽을 수 없어요.')}}});
function network(){const el=$('#networkStatus');if(el)el.innerHTML=navigator.onLine?'':I('wifi-slash')+'<span>오프라인</span>'}window.addEventListener('online',network);window.addEventListener('offline',()=>{network();toast('오프라인이에요. 저장한 장소와 기록은 계속 볼 수 있어요.')});
