function mapPage(){const ps=scoped();return `<div class="map-explorer${sheetFull?' sheet-full':''}" id="mapExplorer"${sheetH?` style="--sheet-height:${sheetH}px"`:''}><div class="map-head"><h1 class="map-title">지도에서 만나는 빛</h1><div class="search-row"><div class="search-box">${I('magnifying-glass')}<input class="search-field" id="placeSearch" type="search" aria-label="지도에서 장소 검색" value="${E(filters.q)}" placeholder="지도에서 장소 검색" autocomplete="off"></div>${filterSheet(ps)}</div>${catChips(ps)}</div><div class="map-stage"><div id="mapCanvas" class="map-placeholder"><div class="map-consent"><span class="map-consent-mark">${I('map-trifold')}</span><h2>좌표가 확인된 공간을 지도에서 보세요</h2><p>지도를 열면 OpenStreetMap 타일 서버에 연결해요. 편집 검증 좌표와 Wikidata 등록 좌표를 구분해 보여드려요.</p><div class="map-consent-actions"><button class="button" data-load-map>${I('map-trifold')}지도 불러오기</button><button type="button" class="button subtle" data-nearby>${I('crosshair')}내 주변 찾기</button></div></div></div><div class="map-fabs"><button type="button" class="glass-button round" data-nearby aria-label="내 위치 주변 보기">${I('crosshair')}</button></div></div><div class="map-list"><button class="map-handle" id="mapHandle" type="button" aria-label="장소 목록 높이 조절, 위아래 방향키 사용"></button><div class="map-list-head">${modeSwitch('map')}</div><div id="mapMessage" role="status"></div><div id="mapResults" tabindex="0" role="region" aria-label="지도 장소 목록">${mapResultHTML()}</div></div></div>`}
// One map at a time: its markers live in one feature group, and every Wikidata circle is drawn by one shared canvas
// renderer (a renderer per rebuild would stack full-size canvases that all redraw on every move). var: render() runs
// before this line on first load.
let mapLibraryPromise=null;var currentMap=null,mapMarkers=[],mapLayer=null,mapRenderer=null,mapShown=[],mapTimer=null;const MAP_TYPING_DELAY=200;
async function loadMap(){const box=$('#mapCanvas'),message=$('#mapMessage');if(!box)return;message.textContent='지도를 불러오는 중…';try{if(!window.L){if(!mapLibraryPromise)mapLibraryPromise=new Promise((resolve,reject)=>{const css=document.createElement('link');css.rel='stylesheet';css.href='./assets/vendor/leaflet/leaflet.css';document.head.appendChild(css);const script=document.createElement('script');script.src='./assets/vendor/leaflet/leaflet.js';const timer=setTimeout(()=>reject(Error('timeout')),12000);script.onload=()=>{clearTimeout(timer);resolve()};script.onerror=()=>{clearTimeout(timer);reject(Error('network'))};document.head.appendChild(script)});await mapLibraryPromise}if(!box.isConnected)return;box.innerHTML='';box.className='map-loaded';currentMap=L.map(box,{zoomControl:false}).setView([37.5665,126.978],10);L.control.zoom({position:'topright',zoomInTitle:'확대',zoomOutTitle:'축소'}).addTo(currentMap);mapRenderer=L.canvas({padding:.5});mapLayer=L.featureGroup().addTo(currentMap);mapShown=[];L.tileLayer(window.AOL_CONFIG?.TILE_URL||'https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a>'}).addTo(currentMap);currentMap.on('moveend',()=>{const target=$('#mapResults');if(target)target.innerHTML=mapResultHTML(currentMap.getBounds())});updateMapResults();if(mapMarkers.length){const verified=mapMarkers.filter(m=>m.aolSource==='verified');currentMap.fitBounds(L.featureGroup(verified.length?verified:mapMarkers).getBounds().pad(.2),{maxZoom:15})}message.textContent='지도를 움직이면 목록도 함께 바뀌어요.'}catch{mapLibraryPromise=null;message.textContent='지도를 불러오지 못했어요. 목록과 상세 정보의 외부 지도 링크를 이용하세요.'}}

// Account-isolated storage: never upload the guest workspace without consent.
let activeUser=null;
const rawStorage=storage;
const scopedStorage={getItem(k){return rawStorage.getItem(k===C.KEY&&activeUser?'aol12_user_'+activeUser:k)},setItem(k,v){return rawStorage.setItem(k===C.KEY&&activeUser?'aol12_user_'+activeUser:k,v)}};
storage=scopedStorage;
window.AOLApp={getDB:()=>db,backup,render,softRender,refreshMedia:softRender,toast,lookup:id=>place(id),places:()=>D.places.filter(p=>p.is_published!==false),
 switchUser(uid){if($('#modal')?.open)$('#modal').close();activeUser=uid;try{const raw=rawStorage.getItem(uid?'aol12_user_'+uid:C.KEY);db=raw?C.validate(JSON.parse(raw),D.places.map(p=>p.place_id)):C.empty();storageBlocked=false}catch{db=C.empty();storageBlocked=true;toast('계정 기록을 읽지 못했어요. 원본은 그대로 보존돼요.')}render()},
 replaceCloud(doc){const next=C.validate(doc,D.places.map(p=>p.place_id));if(!C.write(storage,next))throw Error('기기에 저장하지 못했어요.');db=next;storageBlocked=false;render()},
 mergeGuest(){const guest=C.read(rawStorage,D.places.map(p=>p.place_id));if(guest.blocked)throw Error(guest.warning);const g=guest.data;change(d=>{d.saved=[...new Set([...d.saved,...g.saved])];for(const k of ['visits','routes']){const ids=new Set(d[k].map(x=>x.id));d[k].push(...g[k].filter(x=>!ids.has(x.id)))}const ids=new Set(d.candidates.map(x=>x.place_id));d.candidates.push(...g.candidates.filter(x=>!ids.has(x.place_id)));d.legacyVisits={...g.legacyVisits,...d.legacyVisits}});render()},
 setCatalog(rows){D.places.forEach(p=>p.is_published=false);for(const row of rows){const id=row.place_code||row.id,index=D.places.findIndex(p=>p.place_id===id);const p={...(index>=0?D.places[index]:{}),...row,place_id:id,latitude:row.coordinate_review_status==='verified'?row.latitude:null,longitude:row.coordinate_review_status==='verified'?row.longitude:null,district:row.cities?.name_local||row.cities?.name_en||row.district||'',country:row.cities?.countries?.name_en||'',verified_at:row.verified_at?.slice(0,10)||''};if(index>=0)D.places[index]=p;else D.places.push(p)}catalogVersion++;try{rawStorage.setItem('aol12_public_catalog',JSON.stringify(D.places))}catch{}render()},
 setMedia(rows){window.AOL_MEDIA=rows;render()}
};

// A cleared photo that fails to load (offline, removed upstream) falls back to its original file once, then to the branded
// placeholder in place of the image only: the credit stays, so the source and licence remain one tap away.
document.addEventListener('error',e=>{const img=e.target;if(!img?.matches?.('[data-place-photo]'))return;const original=img.dataset.original;if(original&&img.src!==original){delete img.dataset.original;img.src=original;return}const ph=document.createElement('span');ph.className='photo-pending photo-failed';ph.innerHTML=I('arch','pending-mark')+'<span>사진을 불러오지 못했어요</span><small>출처에서 원본 사진을 확인할 수 있어요</small>';img.replaceWith(ph)},true);

function sectionCards(title,sub,ps,more='<a class="text-link" href="#explore">전체 보기'+I('caret-right')+'</a>'){return `<section class="home-section"><div class="section-head"><div><h2>${E(title)}</h2>${sub?`<small>${E(sub)}</small>`:''}</div><div class="section-tools">${more}${railNav()}</div></div><div class="grid rail rail-scroll">${ps.map(card).join('')}</div></section>`}

function mediaURL(m){return C.safeURL(m.cached_public_url||m.display_url)}
// Photos by place, rebuilt only when a source list changes (thousands of cards may ask). var: the first render runs above.
// NO_MEDIA is the one shared "no photos" value: the cache compares its sources by identity, so a missing source must
// not become a new [] on every call (server snapshot mode, live photo sync off).
var mediaIndex,NO_MEDIA;
function mediaFor(p){
 NO_MEDIA||=Object.freeze([]);
 // After a successful server snapshot, absence must not resurrect revoked seed media.
 const server=window.AOL_MEDIA!==undefined;
 // Browser-side live sync only fills in while no server snapshot exists; the server sync applies the same rules.
 // Photos of places from the nationwide/worldwide Wikidata sync are not in the server snapshot; they pass the same
 // rights checks in the browser (client/global-places.js) and appear only after that check.
 const base=server?window.AOL_MEDIA:(window.AOL_REVIEWED_MEDIA||NO_MEDIA),live=server?NO_MEDIA:(window.AOL_LIVE?.media||NO_MEDIA),global=window.AOL_GLOBAL_MEDIA||NO_MEDIA,list=window.AOL_MEDIA_BLOCKLIST||NO_MEDIA;
 if(!mediaIndex||mediaIndex.base!==base||mediaIndex.live!==live||mediaIndex.global!==global||mediaIndex.list!==list||mediaIndex.n!==base.length+live.length+global.length+list.length){
  const blocked=new Set(list),map=new Map();
  for(const x of [...base,...live,...global]){if(!x||x.review_required||(x.clearance_status&&x.clearance_status!=='cleared')||!mediaURL(x)||blocked.has(x.provider_asset_id)||blocked.has(x.place_code))continue;let rows=map.get(x.place_code);if(!rows)map.set(x.place_code,rows=[]);if(!rows.some(r=>r.provider_asset_id===x.provider_asset_id))rows.push(x)}
  mediaIndex={base,live,global,list,n:base.length+live.length+global.length+list.length,map};
 }
 return mediaIndex.map.get(p.place_id)||[];
}
function globalSyncRows(){const g=window.AOL_GLOBAL;if(!g||g.status==='disabled')return '';const shown=new Set(allPlaces().map(p=>p.place_id)),ps=(g.places||[]).filter(p=>shown.has(p.place_id)),hidden=(g.places||[]).length-ps.length,korea=ps.filter(p=>p.scope==='korea').length,failed=(g.branches||[]).filter(b=>!b.ok),note={stale:' · 최근 갱신 실패, 이전 결과 사용 중',partial:' · 일부 검색 실패',unavailable:' · 지금은 불러올 수 없음',loading:' · 동기화 중…'}[g.status]||'';return `<div class="kv"><dt>전국·세계 장소</dt><dd id="globalSyncCount">국내 ${korea}곳 / 해외 ${ps.length-korea}곳${hidden?` · 수록 장소와 같은 ${hidden}곳 제외`:''}${g.truncated?' · 기기 저장 공간 때문에 일부만 보관':''}</dd></div><div class="kv"><dt>장소 목록 동기화</dt><dd id="globalSyncTime">${E(g.fetchedAt?syncTime(g.fetchedAt):'아직 없음')}${note}</dd></div>${failed.length?`<div class="kv"><dt>실패한 검색</dt><dd id="globalSyncErrors">${failed.map(b=>E(b.id)+' ('+E(b.error||'오류')+')').join(', ')}</dd></div>`:''}`}
function syncTime(iso){const d=new Date(iso);return isNaN(d)?'기록 없음':d.toLocaleString('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}
function liveInfo(p){const i=window.AOL_LIVE?.info?.[p.place_id];if(!i||!/^Q\d+$/.test(i.qid||''))return '';const c=i.coord,osm=c?'https://www.openstreetmap.org/?mlat='+c.lat+'&mlon='+c.lon+'#map=17/'+c.lat+'/'+c.lon:'';return `<section class="detail-section live-info"><h2>공개 데이터 연동 정보</h2>${i.matchKind==='host'?`<p class="section-note">프로젝트가 설치된 건물(${E(i.matchedName)}) 기준 정보입니다.</p>`:''}<dl class="kv-list">${i.website?`<div class="kv"><dt>공식 웹사이트</dt><dd>${link(i.website,'바로가기')}</dd></div>`:''}${c?`<div class="kv"><dt>위치</dt><dd><span class="tnum">${E(c.lat.toFixed(5)+', '+c.lon.toFixed(5))}</span>${link(osm,'지도에서 보기')}</dd></div>`:''}<div class="kv"><dt>출처</dt><dd>${link('https://www.wikidata.org/wiki/'+i.qid,'Wikidata '+i.qid)}${i.commonsCategory?link('https://commons.wikimedia.org/wiki/Category:'+encodeURIComponent(String(i.commonsCategory).replace(/ /g,'_')),'Commons 사진 모음'):''}</dd></div></dl><p class="section-note">Wikidata(CC0)와 Wikimedia Commons에서 6시간마다 자동으로 갱신합니다. 마지막 동기화 ${E(syncTime(i.synced_at))}. 공동 편집 데이터이므로 방문 전 공식 출처를 확인하세요.</p></section>`}

function myPage(){const user=window.AOLCloud?.state?.user;return `<section class="profile-card"><span class="profile-avatar" aria-hidden="true">${I('user')}</span><div class="profile-text"><h1>${user?E(user.email):'나의 빛 아카이브'}</h1><p>${user?'기록을 계정과 동기화하고 있어요':'비회원 모드 · 이 기기에만 저장돼요'}</p></div><a class="button tonal small" href="#account">${user?'계정':'로그인'}</a></section><div class="stat-strip linked">${[['journal','현장 기록',db.visits.length],['routes','답사 코스',db.routes.length],['saved','저장',db.saved.length]].map(([h,t,n])=>`<a class="stat" href="#${h}"><b>${fmt(n)}</b><span>${t}</span></a>`).join('')}</div><h2 class="group-caption">나의 빛</h2><div class="group">${groupRow('#saved','heart','저장한 장소',fmt(db.saved.length)+'곳')}${groupRow('#routes','path','나의 답사 코스',fmt(db.routes.length)+'개')}${groupRow('#calendar','calendar-blank','일정','전시·답사')}${groupRow('#journal','notebook','현장 기록',fmt(db.visits.length)+'개')}</div><h2 class="group-caption">계정 · 데이터</h2><div class="group">${groupRow('#account','user-circle','계정과 동기화',user?'로그인됨':'비회원 모드')}${groupRow('#settings','gear-six','설정','화면·백업')}${groupRow('#audit','list-checks','데이터 검토')}</div><h2 class="group-caption">안내</h2><div class="group">${articles().length?groupRow('#magazine','book-open-text','빛의 건축 읽기'):''}${groupRow('./about.html','info','서비스 소개')}${groupRow('./support.html','lifebuoy','지원 및 문의')}${groupRow('./privacy.html','file-text','개인정보 처리방침')}${groupRow('./terms.html','scroll','이용 안내')}</div><p class="version-foot">빛의 건축 v0.15.0</p>`}

function articles(){return (window.AOL_ARTICLES||[]).filter(a=>a.status==='published'&&a.title&&a.body)}

// Reading time at about 500 Korean characters a minute.
function readMinutes(a){return Math.max(1,Math.round(String(a.body||'').length/500))}
function magazineCards(){return '<div class="article-grid">'+articles().map((a,i)=>`<a class="collection article-card" href="#article/${E(a.id)}"><span class="article-cover brand-art tone-${[0,2,3][i%3]}" aria-hidden="true"><span class="article-no">${String(i+1).padStart(2,'0')}</span>${I('arch','article-mark')}</span><span class="article-text"><span class="article-meta">${E(a.author||'빛의 건축')}${a.published_at?' · '+E(a.published_at.slice(0,10)):''} · ${readMinutes(a)}분</span><h3>${E(a.title)}</h3>${a.summary?`<p>${E(a.summary)}</p>`:''}<span class="text-link">읽기${I('caret-right')}</span></span></a>`).join('')+'</div>'}

function articlePage(id){const a=articles().find(x=>x.id===id);return a?`<article class="article"><header class="article-head"><p class="eyebrow">빛의 건축 읽기</p><h1>${E(a.title)}</h1>${a.summary?`<p class="article-dek">${E(a.summary)}</p>`:''}<p class="article-byline"><span class="byline-mark" aria-hidden="true">${I('arch')}</span><span>${E(a.author||'빛의 건축')}${a.published_at?' · '+E(a.published_at.slice(0,10)):''} · ${readMinutes(a)}분 읽기</span></p></header><div class="record-note article-body">${E(a.body)}</div>${a.source_url?`<p class="article-source">${link(a.source_url,'원문·출처 보기')}</p>`:''}<div class="article-foot"><a class="button tonal" href="#magazine">${I('book-open-text')}다른 글 보기</a><a class="button subtle" href="#routes">${I('path')}에디터 코스</a></div></article>`:notFound()}

function detail(p){if(!p)return notFound();if(isSynced(p))return syncedDetail(p);const f=C.freshness(p),id=E(p.place_id),src=D.sources.filter(s=>s.place_id===p.place_id),gallery=mediaFor(p),mapURL=mapLinkFor(p),reg=X.region(p),c=C.coords(p),meta=[['국가·도시',[reg.country,reg.city].filter(Boolean).join(' · ')],['건축가',p.architect],['작가',p.artist],['제작사',p.producer],['제작·개최 연도',p.project_year],['설치 장소·공간',p.spatial_context],['기술·매체',p.technology],['콘텐츠 유형',p.content_type==='permanent'?'상설':p.content_type==='temporary'?'기간형':'']],related=allPlaces().filter(x=>x.place_id!==p.place_id&&x.primary_category===p.primary_category).slice(0,6);return `<div class="detail">${detailHero(p)}<div class="detail-sheet"><div class="detail-body"><header class="detail-title"><p class="eyebrow">${E(category(p))}${p.district?' · '+E(p.district):''}</p><h1>${E(p.name_kr)}</h1>${p.name_en?`<p class="detail-sub">${E(p.name_en)}</p>`:''}<div class="detail-pills">${badge(p)}${p.free===true?'<span class="pill">무료</span>':''}${p.indoor===true?'<span class="pill">실내</span>':p.indoor===false?'<span class="pill">야외</span>':''}</div></header>${quickActions(p,mapURL)}${sectionTabs(related.length,!!(p.short_description||p.why_it_matters))}${p.short_description||p.why_it_matters?`<div class="detail-lead" id="detailAbout">${p.short_description?`<p class="detail-description">${E(p.short_description)}</p>`:''}${p.why_it_matters?`<p class="quote">${E(p.why_it_matters)}</p>`:''}</div>`:''}<aside class="detail-aside" id="detailInfo"><div class="info-card"><h2>방문 전 확인</h2><dl class="kv-list"><div class="kv"><dt>주소</dt><dd>${E(p.address||'주소 미확인')}</dd></div><div class="kv"><dt>운영시간</dt><dd>${E(p.current_hours_verified||p.typical_hours||'확인 필요')}${p.recommended_time?`<small>추천 시간 ${E(p.recommended_time)}</small>`:''}</dd></div><div class="kv"><dt>요금</dt><dd>${p.free===true?'무료로 수록':p.free===false?'유료·조건부로 수록':'미확인'}</dd></div><div class="kv"><dt>확인일</dt><dd>${E(p.verified_at||'없음')}${f.age!==null?` · ${f.age}일 경과`:''}</dd></div><div class="kv"><dt>좌표</dt><dd>${c?E(c.join(', '))+' · 외부 출처 제공':'미확인 · 주소 검색 사용'}</dd></div></dl><div class="notice warning">${I('warning')}<span>${E(f.label)}. 수록 정보는 현재 영업·상영을 보장하지 않아요. 운영시간과 휴무는 공식 출처에서 확인하세요.</span></div><div class="info-actions"><button class="button large" data-add-route="${id}">${I('plus')}답사 코스에 담기</button>${link(mapURL,'지도에서 주소 검색','button subtle large')}</div></div></aside><div class="detail-main"><section class="detail-section"><h2>빛의 건축 해설</h2><p class="reading">${E(p.expert_description||p.description||'세계 검색 결과는 아직 에디토리얼 검토 전입니다.')}</p><details class="research-details"><summary>프로젝트 상세정보</summary><dl class="kv-list">${meta.map(([k,v])=>`<div class="kv"><dt>${E(k)}</dt><dd>${E(v||'정보 미등록')}</dd></div>`).join('')}</dl></details></section><section class="detail-section" id="detailPhotos"><h2>사진과 출처</h2>${gallery.length?`<div class="image-gallery">${gallery.map(m=>figureHTML(p,m)).join('')}</div>`:''}<p class="section-note">Wikidata에 연결된 Wikimedia Commons 사진을 6시간마다 자동으로 가져와 촬영자·라이선스·원본 링크와 함께 보여드려요. 사진은 촬영 당시 모습이며 지금의 전시·상영 상태를 뜻하지 않아요. 아래 버튼의 추가 검색 결과는 장소 일치가 확인되지 않은 후보예요. 사진 권리 문제는 <a href="./support.html">지원 페이지</a>로 알려주시면 바로 내립니다.</p><button class="button subtle" data-load-photo="${id}">${I('images')}공개 이미지 후보 확인</button><div id="photoResult"></div></section><section class="detail-section"><h2>수록 프로그램과 출처</h2><p class="program-name">${E(p.current_program||'현재 프로그램 미확인')}</p>${p.program_start||p.program_end?`<p class="section-note tnum">${E(p.program_start||'')}${p.program_end?' – '+E(p.program_end):''}</p>`:''}${p.verification_note?`<p class="section-note">${E(p.verification_note)}</p>`:''}<div class="source-links">${link(official(p),'대표 출처')}${link(p.verification_source_2,'추가 확인 출처')}${src.slice(0,2).map(s=>link(s.url,s.publisher||'데이터 출처')).join('')}</div></section>${liveInfo(p)}${visitsSection(p)}</div></div>${related.length?`<div id="detailRelated">${sectionCards('같은 유형의 프로젝트','유형을 기준으로 연결했어요',related)}</div>`:''}</div>${actionBar(p,mapURL)}</div>`}

function figureHTML(p,m){return `<figure class="gallery-figure"><a class="gallery-photo" href="${E(mediaURL(m))}" target="_blank" rel="noopener noreferrer"><img class="photo" src="${E(mediaURL(m))}" alt="${E(p.name_kr)}" loading="lazy" data-place-photo data-original="${E(C.safeURL(m.original_file_url))}"></a><figcaption><b class="credit-line">© ${E(m.creator||'작성자 표기 확인 필요')} · ${E(m.license_code||'')}</b><span>${[m.captured_at?'촬영 '+E(m.captured_at):'',E(m.caption||'장소 사진'),E(m.changes||''),m.last_rights_sync_at?'권리 확인 '+E(String(m.last_rights_sync_at).slice(0,10)):''].filter(Boolean).join(' · ')}</span><span class="figure-links">${link(m.source_url,'이미지 원본')}${link(m.license_url,'사용조건')}</span></figcaption></figure>`}

const PHOTO_REASONS={license_not_allowed:'자유 라이선스(CC BY·CC BY-SA·CC0·퍼블릭 도메인)가 아님',unsupported_type:'지원하지 않는 파일 형식',commons_deletion_or_permission_issue:'Commons에 삭제·허가 문제 표시가 있음',kr_freedom_of_panorama_disabled:'한국 파노라마의 자유 사진 표시가 꺼져 있음',foreign_no_freedom_of_panorama:'파노라마의 자유가 없는 나라의 건축물·작품 사진',commons_templates_incomplete:'Commons의 저작권 표시 목록을 끝까지 확인하지 못함',missing:'Commons에서 파일을 찾을 수 없음'};
function syncedPhotoNote(p){if(!p.image)return 'Wikidata 항목에 대표 사진(P18)이 등록되어 있지 않습니다.';const s=window.AOLGlobal?.imageStatus?.(p.place_id);if(s?.state==='blocked')return E('대표 사진(P18)은 자동 표시 조건에 맞지 않아 표시하지 않습니다: '+s.reasons.map(r=>PHOTO_REASONS[r]||r).join(', ')+'.');return (s?.state==='pending'?'대표 사진(P18)의 권리를 확인하는 중입니다. ':'')+'Wikidata 항목의 대표 사진(P18)은 라이선스(CC BY·CC BY-SA·CC0·퍼블릭 도메인)와 삭제·파노라마의 자유 제한 표시를 확인한 뒤에만 촬영자·라이선스·원본 링크와 함께 표시합니다.'}
// A place from the 6-hourly Wikidata sync: only what Wikidata publishes, with its source; no hours, fees or programmes.
function syncedDetail(p){const id=E(p.place_id),qid=p.wikidata||p.place_id.slice(3),c=C.coords(p),osm=c?`https://www.openstreetmap.org/?mlat=${c[0]}&mlon=${c[1]}#map=16/${c[0]}/${c[1]}`:'',gallery=mediaFor(p),cats=[...new Set((p.categories?.length?p.categories:[p.primary_category]).map(k=>category({primary_category:k})))],at=window.AOL_GLOBAL?.fetchedAt,related=allPlaces().filter(x=>x.place_id!==p.place_id&&x.primary_category===p.primary_category&&X.region(x).country===X.region(p).country).slice(0,6);return `<div class="detail">${detailHero(p)}<div class="detail-sheet"><div class="detail-body"><header class="detail-title"><p class="eyebrow">${E(category(p))}${regionText(p)?' · '+E(regionText(p)):''}</p><h1>${E(p.name_kr)}</h1>${p.name_en&&p.name_en!==p.name_kr?`<p class="detail-sub">${E(p.name_en)}</p>`:''}<div class="detail-pills">${badge(p)}</div></header>${quickActions(p,osm)}${sectionTabs(related.length,!!p.short_description)}${p.short_description?`<div class="detail-lead" id="detailAbout"><p class="detail-description">${E(p.short_description)}</p></div>`:''}<aside class="detail-aside" id="detailInfo"><div class="info-card synced-info"><h2>장소 정보</h2><dl class="kv-list"><div class="kv"><dt>유형</dt><dd>${E(cats.join(' · '))}</dd></div><div class="kv"><dt>국가·도시</dt><dd>${E(regionText(p)||'미확인')}</dd></div><div class="kv"><dt>좌표</dt><dd>${c?`<span class="tnum">${E(c[0].toFixed(5)+', '+c[1].toFixed(5))}</span> · Wikidata 등록 좌표`+link(osm,'OpenStreetMap에서 보기'):'미확인'}</dd></div><div class="kv"><dt>공식 웹사이트</dt><dd>${p.website?link(p.website,'바로가기'):'Wikidata에 등록되지 않음'}</dd></div><div class="kv"><dt>출처</dt><dd>${link('https://www.wikidata.org/wiki/'+qid,'Wikidata '+qid)}</dd></div></dl><div class="info-actions"><button class="button large" data-add-route="${id}">${I('plus')}답사 코스에 담기</button></div></div><div class="notice warning synced-note">${I('info')}<span>Wikidata 공동 편집 데이터 · 6시간마다 자동 갱신 · 방문 전 공식 정보 확인</span></div><p class="aside-note">${at?'마지막 동기화 '+E(syncTime(at))+'. ':''}운영시간·요금·일정은 제공하지 않아요. 좌표와 설명은 Wikidata(CC0)에 등록된 값이며 편집 검토 전이에요.</p></aside><div class="detail-main"><section class="detail-section" id="detailPhotos"><h2>사진과 출처</h2>${gallery.length?`<div class="image-gallery">${gallery.map(m=>figureHTML(p,m)).join('')}</div>`:`<p class="section-note" id="syncedPhotoStatus">${syncedPhotoNote(p)}</p>`}<p class="section-note">사진 권리 문제는 <a href="./support.html">지원 페이지</a>로 알려주시면 바로 내립니다.</p></section>${visitsSection(p)}</div></div>${related.length?`<div id="detailRelated">${sectionCards('같은 유형의 장소','같은 나라, 같은 유형으로 연결했어요',related)}</div>`:''}</div>${actionBar(p,osm)}</div>`}

function mapProjects(){return X.search(scoped(),filters,C.today()).filter(X.mappable)}

function mapResultHTML(bounds,all=mapProjects()){const wd=all.filter(X.wikidataCoords).length,ps=bounds?all.filter(p=>bounds.contains([p.latitude,p.longitude])):all,shown=ps.slice(0,showCount);return `<div class="result-meta"><b>${bounds?'이 지역':E(scopeLabel())} · ${fmt(ps.length)}곳</b><span>검증 좌표 ${all.length-wd}곳 · Wikidata 좌표 ${wd}곳</span></div>${shown.map(p=>{const w=X.wikidataCoords(p);return `<button class="map-list-item" data-map-select="${E(p.place_id)}"><span class="map-item-icon${w?' wd':''}">${I(catIcon(p))}</span><span class="map-item-text"><b>${E(p.name_kr)}</b><small>${E([category(p),regionText(p)].filter(Boolean).join(' · '))}</small><small class="coord-tag">${w?'Wikidata 좌표':'검증 좌표'}</small></span>${I('caret-right','map-item-caret')}</button>`}).join('')||empty('이 영역에는 좌표가 확인된 장소가 없어요','지도를 넓히거나 필터를 바꿔 보세요. 출처 없는 추정 좌표는 표시하지 않아요.')}${ps.length>shown.length?`<button class="button subtle more-button" data-more>${fmt(Math.min(PAGE,ps.length-shown.length))}곳 더 보기</button>`:''}`}

function updateMapList(all){const el=$('#mapResults');if(el)el.innerHTML=mapResultHTML(currentMap?.getBounds(),all)}
// Editorially verified coordinates are pins; coordinates published on Wikidata are small circles drawn on the map's one
// canvas renderer (thousands stay fast) and their popup names the source. Markers are rebuilt only when the list of
// places changed (typing is debounced; a background update that changes nothing on the map keeps them).
function updateMapResults(){clearTimeout(mapTimer);mapTimer=null;if(!$('#mapResults'))return;const ps=mapProjects();updateMapList(ps);if(!currentMap||!mapLayer)return;if(ps.length===mapShown.length&&ps.every((p,i)=>p===mapShown[i]))return;mapShown=ps;mapLayer.clearLayers();mapMarkers=[];for(const p of ps){const wd=X.wikidataCoords(p),pop=`<div class="map-pop"><p class="map-pop-eyebrow">${E(category(p))}</p><a href="#place/${E(p.place_id)}"><b>${E(p.name_kr)}</b> 상세 보기${I('caret-right','icon-sm')}</a>${regionText(p)?`<small>${E(regionText(p))}</small>`:''}<small class="map-pop-source">${wd?'좌표 출처: Wikidata 등록 좌표 · 편집 검토 전':'좌표 출처: 편집 검증 좌표'}</small></div>`;const m=wd?L.circleMarker([p.latitude,p.longitude],{renderer:mapRenderer,radius:7,weight:2,color:'#FFFFFF',fillColor:'#6B52DE',fillOpacity:1}).bindPopup(pop):L.marker([p.latitude,p.longitude],{icon:L.divIcon({className:'map-pin',html:`<span class="pin-body">${I(catIcon(p))}</span>`,iconSize:[36,36],iconAnchor:[18,18],popupAnchor:[0,-16]}),title:p.name_kr}).bindPopup(pop);m.aolId=p.place_id;m.aolSource=wd?'wikidata':'verified';mapLayer.addLayer(m);mapMarkers.push(m)}}

async function privatePhotos(visitId){if(!window.AOLCloud?.state.user){toast('개인 사진은 로그인하고 서버에 연결한 뒤 쓸 수 있어요.');return}const uid=window.AOLCloud.state.user.id,el=modal('나만의 현장 사진',`<p class="muted">사진은 비공개 저장소에 보관해요. 올리기 전에 촬영 메타데이터를 지우고 긴 변 2,048px 이하 JPEG로 바꿔요. JPG·PNG·WebP, 파일당 5MB 이하예요. JSON 백업에는 사진 파일이 들어가지 않아요.</p><input id="privatePhotoInput" type="file" accept="image/jpeg,image/png,image/webp" aria-label="개인 사진 선택"><div id="privatePhotoStatus" role="status"></div><div id="privatePhotoList"></div>`);const status=$('#privatePhotoStatus'),list=$('#privatePhotoList');const show=async()=>{const rows=await window.AOLCloud.photos.list(visitId);if(!el.open||window.AOLCloud.state.user?.id!==uid)return;list.innerHTML=rows.map(p=>`<figure><img class="photo" src="${E(C.safeURL(p.url))}" alt="나의 방문 사진"><button class="button danger small" data-private-delete="${E(p.id)}">사진 삭제</button></figure>`).join('')||'<p>첨부한 사진이 없어요.</p>';list.querySelectorAll('[data-private-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('이 사진을 영구 삭제할까요?'))return;try{await window.AOLCloud.photos.remove(b.dataset.privateDelete);await show()}catch(e){status.textContent=e.message}})};$('#privatePhotoInput').onchange=async e=>{const file=e.target.files[0];if(!file)return;status.textContent='사진을 저장하는 중…';try{await window.AOLCloud.photos.upload(visitId,file);await show();status.textContent='저장했어요.'}catch(e){status.textContent=e.message}e.target.value=''};try{await show()}catch(e){status.textContent=e.message}}

// One of four brand gradients per place, so a grid of places without photos does not repeat one box.
function tone(id){let h=0;for(const ch of String(id||''))h=(h*31+ch.charCodeAt(0))>>>0;return h%4}
function railNav(){return `<span class="rail-nav" hidden><button type="button" class="rail-btn" data-rail-step="-1" aria-label="이전 항목 보기" disabled>${I('caret-left')}</button><button type="button" class="rail-btn" data-rail-step="1" aria-label="다음 항목 보기">${I('caret-right')}</button></span>`}
// Desktop rails are one row (3 or 4 cards) that scrolls sideways; the arrows show only when there is more to see.
function railState(){for(const r of document.querySelectorAll?.('.rail-scroll')||[]){const nav=r.closest('section')?.querySelector('.rail-nav');if(!nav)continue;const update=()=>{const max=r.scrollWidth-r.clientWidth;nav.hidden=max<8;const [prev,next]=nav.querySelectorAll('button');if(prev)prev.disabled=r.scrollLeft<8;if(next)next.disabled=r.scrollLeft>max-8};r.onscroll=update;update()}}
// Place page: sticky section tabs (정보 is the info card, shown next to the content on desktop) with scroll-spy.
function sectionTabs(related,about){return `<nav class="section-tabs" aria-label="장소 정보 바로가기">${[...(about?[['detailAbout','소개']]:[]),['detailInfo','정보'],['detailPhotos','사진'],['detailVisits','내 기록'],...(related?[['detailRelated','비슷한 곳']]:[])].map(([id,t],i)=>`<button type="button" class="${id==='detailInfo'?'tab-info':''}${i===0?' active':''}" data-scroll-to="${id}">${t}</button>`).join('')}</nav>`}
function spyTabs(){const tabs=[...document.querySelectorAll?.('.section-tabs button')||[]].filter(b=>b.offsetParent!==null);if(!tabs.length)return;const line=(document.querySelector('.section-tabs')?.getBoundingClientRect().bottom||0)+24;let cur=tabs[0];for(const b of tabs){const el=document.getElementById(b.dataset.scrollTo);if(el&&el.getBoundingClientRect().top<=line)cur=b}if((window.innerHeight+window.scrollY)>=document.documentElement.scrollHeight-4)cur=tabs[tabs.length-1];for(const b of tabs){b.classList.toggle('active',b===cur);if(b===cur)b.setAttribute('aria-current','true');else b.removeAttribute('aria-current')}}